mapper.select:
SELECT o.EMPNO                        AS empno,
       NVL(h.EMP_NM, '미분류')        AS empNm,
       NVL(h.PART_CD, '미분류')       AS partCd,
       o.OT_MINUTES                   AS otMinutes
  FROM HR_OVERTIME o
  LEFT JOIN HR_DEVELOPER h ON o.EMPNO = h.EMPNO
 WHERE o.PERIOD_YM = #{period}

   AND o.EMPNO = #{empno}


   AND NVL(h.DEPT_CD, '미분류') = #{dept}


   AND NVL(h.PART_CD, '미분류') = #{part}

 ORDER BY o.OT_MINUTES DESC, o.EMPNO

SELECT COUNT(*)
  FROM HR_DEVELOPER h
 WHERE h.STATUS_CD = '01'
   AND h.DEV_YN = 'Y'

   AND NVL(h.DEPT_CD, '미분류') = #{dept}


   AND NVL(h.PART_CD, '미분류') = #{part}


   AND h.EMPNO = #{empno}

SELECT h.EMPNO AS empno, h.EMP_NM AS empNm, NVL(h.DEPT_CD, '미분류') AS deptCd, NVL(h.PART_CD, '미분류') AS partCd, h.DEV_YN AS devYn, NVL(SUM(d.JOB_MM), 0) AS usedMm FROM HR_DEVELOPER h LEFT JOIN DASH_DEV_AGG d ON d.EMPNO = h.EMPNO AND d.PERIOD_YM = #{period} WHERE h.STATUS_CD = '01' AND h.DEV_YN = 'Y'
AND NVL(h.DEPT_CD, '미분류') = #{dept}
AND NVL(h.PART_CD, '미분류') = #{part}
AND h.EMPNO = #{empno}
GROUP BY h.EMPNO, h.EMP_NM, h.DEPT_CD, h.PART_CD, h.DEV_YN ORDER BY usedMm DESC, h.EMPNO
